/* C API of the Rust port of `prime_numbers.c`, generated by rust-anything. */
#ifndef PRIME_NUMBERS_RS_H
#define PRIME_NUMBERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

bool slow_is_prime_number(unsigned long x);
unsigned long next_prime_number(unsigned long x);
bool is_prime_number(unsigned long x);

/* The same functions under `rust_anything_` names, for shadow runs. */
bool rust_anything_slow_is_prime_number(unsigned long x);
unsigned long rust_anything_next_prime_number(unsigned long x);
bool rust_anything_is_prime_number(unsigned long x);

#endif /* PRIME_NUMBERS_RS_H */
